INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-CARD-083', 'Ventricular septal defect', 'Ventricular septal defect is a clinically distinct cardiology entity: Congenital structural lesions alter pulmonary and systemic flow, producing shunt physiology or outflow obstruction.', 'Cardiology', '2', 'acute when symptoms evolve over minutes to days; chronic phenotypes require longitudinal assessment', 'emergent when perfusion, oxygenation, or electrical stability is threatened', 'Family history, chromosomal syndromes, maternal exposures, and prenatal imaging context may be relevant.', 'Family history, chromosomal syndromes, maternal exposures, and prenatal imaging context may be relevant.', 'Congenital structural lesions alter pulmonary and systemic flow, producing shunt physiology or outflow obstruction.', 'Feeding difficulty, cyanosis, tachypnea, poor growth, differential pulses, or a murmur can be early clues.', 'Cyanosis, shunt direction, pulse findings, and echocardiography distinguish lesions; ductal dependence changes urgent stabilization.', 'Do not equate a reassuring single test, a murmur label, or a stable-looking rhythm with exclusion of a high-risk process; use the defining physiology and clinical context.', 'Profound cyanosis, shock after ductal closure, respiratory failure, or poor perfusion requires immediate neonatal or pediatric escalation.', 'Suspected ductal-dependent lesions require monitored specialty care and rapid congenital-cardiology input.', 'Outcome depends on anatomy, pulmonary vascular remodeling, timing of repair, and associated syndromes.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary; source checked against linked public authoritative guidance and awaiting qualified clinician review.');
