INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-034', 'First unprovoked seizure', 'First unprovoked seizure is a neurologic entity in which hypersynchronous cortical activity causes a seizure phenotype defined by onset and awareness.', 'Neurology', '1', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Structural injury, genetic epilepsy, infection, withdrawal, medications, and metabolic derangement are key causes.', 'Structural injury, genetic epilepsy, infection, withdrawal, medications, and metabolic derangement are key causes.', 'Hypersynchronous cortical activity causes a seizure phenotype defined by onset and awareness.', 'Witnessed semiology, recovery, tongue injury, focal deficit, and provoking factors frame classification.', 'Check glucose and cardiorespiratory stability first; EEG, imaging, and LP are selected by persistent deficit, infection concern, or altered recovery.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Persistent seizure, pregnancy-associated seizure, fever with meningismus, trauma, or failure to recover is high risk.', 'Status needs immediate stabilization and sequential antiseizure treatment; a first event needs cause-focused disposition.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
