INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-053', 'Migraine without aura', 'Migraine without aura is a neurologic entity in which primary headache syndromes and secondary intracranial processes overlap in pain presentation.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Migraine history, vascular risk, immunocompromise, pregnancy, malignancy, trauma, and medication exposure alter risk.', 'Migraine history, vascular risk, immunocompromise, pregnancy, malignancy, trauma, and medication exposure alter risk.', 'Primary headache syndromes and secondary intracranial processes overlap in pain presentation.', 'Onset pattern, aura, autonomic features, fever, neurologic deficit, and papilledema distinguish pathways.', 'Thunderclap onset, focal signs, meningismus, papilledema, or exertional trigger warrants urgent secondary-headache evaluation.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Sudden maximal pain, altered consciousness, visual loss, or fever requires emergency escalation.', 'Dangerous secondary causes require acute imaging or targeted testing; uncomplicated primary headache uses phenotype-based therapy.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
