INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-062', 'Acute bacterial meningitis', 'Acute bacterial meningitis is a neurologic entity in which infection of meninges, brain, or spinal epidural space can rapidly injure neural tissue.', 'Neurology', '1', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Age, immunocompromise, exposure, neurosurgery, sinus or ear disease, and bacteremia guide probability.', 'Age, immunocompromise, exposure, neurosurgery, sinus or ear disease, and bacteremia guide probability.', 'Infection of meninges, brain, or spinal epidural space can rapidly injure neural tissue.', 'Fever, headache, neck stiffness, encephalopathy, focal signs, or seizures are key patterns.', 'Blood cultures and empiric therapy must not be delayed for procedures when instability or high suspicion exists; imaging precedes LP in selected mass-effect risk.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Shock, seizure, focal deficit, reduced consciousness, or spinal cord signs require urgent treatment and consultation.', 'Hospital care, microbiologic confirmation, and neurocritical monitoring are determined by severity and cause.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
