INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-N-0065', 'Multiple sclerosis', 'Multiple sclerosis is a neurologic entity in which immune-mediated injury to central or peripheral myelin produces multifocal deficits.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Autoimmune history, infection trigger, age, optic symptoms, and prior attacks direct the differential.', 'Autoimmune history, infection trigger, age, optic symptoms, and prior attacks direct the differential.', 'Immune-mediated injury to central or peripheral myelin produces multifocal deficits.', 'Optic neuritis, myelopathy, sensory level, weakness, or encephalopathy localize the syndrome.', 'MRI distribution, CSF studies, antibody testing, EMG, and respiratory measures distinguish central from peripheral disease.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Rapid weakness, bulbar symptoms, autonomic instability, or respiratory decline requires monitored escalation.', 'Acute relapse and neuromuscular failure need mechanism-specific immunotherapy planning and rehabilitation.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
