INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-N-0068', 'Guillain-Barre syndrome', 'Guillain-Barre syndrome is a neurologic entity in which neuromuscular-junction, muscle, or peripheral motor disease causes patterned weakness.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Autoimmunity, malignancy, toxin exposure, medications, family history, and infection are relevant.', 'Autoimmunity, malignancy, toxin exposure, medications, family history, and infection are relevant.', 'Neuromuscular-junction, muscle, or peripheral motor disease causes patterned weakness.', 'Fatigability, ocular or bulbar signs, proximal weakness, reflex pattern, CK, and sensory involvement localize disease.', 'Respiratory mechanics, antibodies, EMG, nerve conduction, CK, and imaging are chosen by localization.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Bulbar weakness, declining respiratory measures, aspiration, or autonomic instability needs critical monitoring.', 'Crisis requires monitored respiratory support and mechanism-specific rescue therapy.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
