INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-N-0066', 'Parkinson disease', 'Parkinson disease is a neurologic entity in which basal-ganglia, cerebellar, medication, or systemic dysfunction changes movement amplitude, rhythm, and tone.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Medication exposure, family history, liver disease, toxins, and age at onset help classify movement disorders.', 'Medication exposure, family history, liver disease, toxins, and age at onset help classify movement disorders.', 'Basal-ganglia, cerebellar, medication, or systemic dysfunction changes movement amplitude, rhythm, and tone.', 'Resting versus action tremor, bradykinesia, rigidity, chorea, dystonia, and autonomic signs are discriminators.', 'Focused examination and medication review usually lead; targeted imaging or metabolic testing follows atypical features.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Hyperthermia, rigidity, autonomic instability, or rhabdomyolysis signals a life-threatening medication syndrome.', 'Disposition follows functional safety, medication toxicity, and need for specialty management.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
