INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-096', 'Alzheimer disease', 'Alzheimer disease is a neurologic entity in which neurodegeneration, vascular injury, delirium, and nutritional disease impair attention, memory, or executive function.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Age, vascular disease, medications, alcohol exposure, infection, mood symptoms, and trajectory are essential context.', 'Age, vascular disease, medications, alcohol exposure, infection, mood symptoms, and trajectory are essential context.', 'Neurodegeneration, vascular injury, delirium, and nutritional disease impair attention, memory, or executive function.', 'Acute fluctuating inattention favors delirium; progressive domain-specific decline favors dementia syndrome.', 'Collateral history, cognitive testing, medication review, laboratory evaluation, and selective imaging identify reversible contributors.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Acute attention change, unsafe behavior, focal deficit, or impaired capacity requires urgent assessment.', 'Safety, caregiver support, driving, capacity, and treatment of reversible causes shape disposition.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
