INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-113', 'Diabetic polyneuropathy', 'Diabetic polyneuropathy is a neurologic entity in which peripheral nerve injury or length-dependent neuropathy causes deficits in a nerve, root, or stocking distribution.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Diabetes, alcohol, nutritional deficiency, compression, trauma, chemotherapy, and autoimmune disease are common causes.', 'Diabetes, alcohol, nutritional deficiency, compression, trauma, chemotherapy, and autoimmune disease are common causes.', 'Peripheral nerve injury or length-dependent neuropathy causes deficits in a nerve, root, or stocking distribution.', 'Motor pattern, sensory territory, reflex loss, and provoking posture distinguish nerve from root or plexus disease.', 'Focused examination and electrodiagnostic testing refine localization; imaging is selected for compressive or atypical patterns.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Rapid progression, motor deficit, sphincter symptoms, or systemic vasculitic features needs urgent evaluation.', 'Conservative protection, cause treatment, rehabilitation, and surgery assessment depend on deficit and compression.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
