INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-120', 'Cauda equina syndrome', 'Cauda equina syndrome is a neurologic entity in which cord, conus, cauda, root, or motor-neuron pathology produces tract-specific weakness and sensory change.', 'Neurology', '1', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Malignancy, infection, trauma, degenerative disease, anticoagulation, and inflammatory disease increase risk.', 'Malignancy, infection, trauma, degenerative disease, anticoagulation, and inflammatory disease increase risk.', 'Cord, conus, cauda, root, or motor-neuron pathology produces tract-specific weakness and sensory change.', 'Sensory level, saddle anesthesia, bowel or bladder dysfunction, reflexes, and upper versus lower motor-neuron signs localize lesions.', 'Urgent MRI is central for suspected compression; do not delay emergency escalation for progressive deficits.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Saddle anesthesia, urinary retention, rapidly progressive weakness, fever, or cancer history is emergent.', 'Compression and cauda syndromes require urgent surgical or specialty disposition.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
