INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-129', 'Glioblastoma', 'Glioblastoma is a neurologic entity in which primary or metastatic intracranial mass causes focal dysfunction, seizures, raised pressure, or endocrine effects by location.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Age, cancer history, immune status, inherited syndromes, and progressive symptoms guide probability.', 'Age, cancer history, immune status, inherited syndromes, and progressive symptoms guide probability.', 'Primary or metastatic intracranial mass causes focal dysfunction, seizures, raised pressure, or endocrine effects by location.', 'New seizure, progressive focal deficit, personality change, raised-pressure symptoms, or visual-field change may occur.', 'Contrast MRI characterizes location and mass effect; tissue diagnosis and staging follow specialist assessment.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Herniation signs, declining consciousness, severe edema, or acute hydrocephalus require emergency neurocritical care.', 'Neurosurgical, oncology, and radiation planning depends on anatomy, pathology, and mass effect.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
