INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-137', 'Increased intracranial pressure', 'Increased intracranial pressure is a neurologic entity in which raised intracranial pressure or impaired csf flow can compromise perfusion and cause herniation.', 'Neurology', '1', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Mass lesion, hemorrhage, infection, hydrocephalus, venous thrombosis, and medication context are major causes.', 'Mass lesion, hemorrhage, infection, hydrocephalus, venous thrombosis, and medication context are major causes.', 'Raised intracranial pressure or impaired CSF flow can compromise perfusion and cause herniation.', 'Headache, vomiting, papilledema, cranial-nerve palsy, declining consciousness, and posturing suggest pressure physiology.', 'Neuroimaging precedes LP when mass effect or obstructive hydrocephalus is suspected.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Cushing response, unilateral fixed pupil, posturing, or coma is an immediate emergency.', 'Neurocritical monitoring, cause-directed decompression, and CSF diversion consultation may be required.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
