INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-142', 'Oculomotor nerve palsy', 'Oculomotor nerve palsy is a neurologic entity in which cranial-nerve or brainstem pathway disease produces focal ocular, facial, sensory, or bulbar deficits.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Vascular risk, aneurysm concern, infection, demyelination, trauma, and tumor context direct evaluation.', 'Vascular risk, aneurysm concern, infection, demyelination, trauma, and tumor context direct evaluation.', 'Cranial-nerve or brainstem pathway disease produces focal ocular, facial, sensory, or bulbar deficits.', 'Pupil findings, eye-movement pattern, facial distribution, hearing, and long-tract signs provide localization.', 'Pupil-involving third-nerve palsy or crossed brainstem findings needs urgent vascular or structural imaging.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Acute painful pupil involvement, brainstem signs, or vision loss needs emergency evaluation.', 'Disposition follows localization, aneurysm exclusion, corneal protection, and specialty follow-up.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
