INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-146', 'Benign paroxysmal positional vertigo', 'Benign paroxysmal positional vertigo is a neurologic entity in which vestibular, cerebellar, sensory, or cardiovascular processes produce spinning, imbalance, or presyncope.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Vascular risk, hearing change, positional trigger, migraine, medication, and orthostatic context are informative.', 'Vascular risk, hearing change, positional trigger, migraine, medication, and orthostatic context are informative.', 'Vestibular, cerebellar, sensory, or cardiovascular processes produce spinning, imbalance, or presyncope.', 'Nystagmus direction, gait, hearing, focal signs, and positional provocation separate peripheral from central processes.', 'Central warning signs or inability to walk warrant neuroimaging; bedside eye testing is context-dependent and examiner-sensitive.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'New focal deficit, severe gait ataxia, headache, or persistent central nystagmus is high risk.', 'Central disease requires emergency stroke evaluation; peripheral disease uses targeted vestibular management.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
