INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-150', 'Cerebral palsy', 'Cerebral palsy is a neurologic entity in which developmental, genetic, motor, or epileptic syndromes alter age-expected neurologic function.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Prenatal history, family history, head growth, regression, feeding, tone, and seizure timing are key.', 'Prenatal history, family history, head growth, regression, feeding, tone, and seizure timing are key.', 'Developmental, genetic, motor, or epileptic syndromes alter age-expected neurologic function.', 'Milestone loss, hypotonia, spasticity, dysmorphism, focal seizures, and skin findings guide localization and testing.', 'Developmental assessment, genetics, MRI, metabolic testing, and EEG are selected by phenotype.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Regression, neonatal hypotonia with respiratory compromise, or infantile spasms needs urgent specialty evaluation.', 'Early multidisciplinary pediatric neurology, rehabilitation, genetic counseling, and family support are central.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
