INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-NEUR-155', 'Hepatic encephalopathy', 'Hepatic encephalopathy is a neurologic entity in which metabolic, nutritional, withdrawal, or toxin-mediated injury impairs brain, nerve, or muscle function.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Organ failure, malnutrition, medication exposure, alcohol use, environmental exposure, and electrolyte shifts are central risks.', 'Organ failure, malnutrition, medication exposure, alcohol use, environmental exposure, and electrolyte shifts are central risks.', 'Metabolic, nutritional, withdrawal, or toxin-mediated injury impairs brain, nerve, or muscle function.', 'Fluctuating consciousness, tremor, ataxia, neuropathy, myopathy, or autonomic findings suggest systemic injury.', 'Targeted metabolic tests, exposure history, and imaging or EEG clarify neurologic involvement.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Coma, seizure, hyperthermia, severe acidosis, or rapidly progressive deficit is emergent.', 'Treat the identified toxin or metabolic disturbance while protecting airway and avoiding harmful rapid correction.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
