INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-P-0023', 'Obstructive sleep apnea', 'Obstructive sleep apnea is a neurologic entity in which sleep-wake regulation, airway, or movement disorders impair restorative sleep and daytime vigilance.', 'Neurology', '2', 'acute, subacute, or progressive according to the defining syndrome and onset pattern', 'emergent when airway, perfusion, consciousness, vision, or progressive neurologic function is threatened', 'Obesity, sedatives, neurologic disease, circadian disruption, iron deficiency, and psychiatric comorbidity are relevant.', 'Obesity, sedatives, neurologic disease, circadian disruption, iron deficiency, and psychiatric comorbidity are relevant.', 'Sleep-wake regulation, airway, or movement disorders impair restorative sleep and daytime vigilance.', 'Snoring, witnessed apnea, cataplexy, dream enactment, urge to move legs, and sleep timing distinguish syndromes.', 'Sleep history, medication review, polysomnography, and multiple sleep latency testing are selected by phenotype.', 'Do not substitute a single normal screening test, a nonspecific symptom, or a stable interval examination for localization and time-sensitive risk assessment.', 'Drowsy driving, severe hypoxemia, or sudden loss of tone requires immediate safety counseling.', 'Management addresses safety, comorbid disease, and disorder-specific sleep medicine referral.', 'Outcome depends on timely mechanism-specific treatment, lesion burden, recurrence prevention, rehabilitation, and systemic comorbidity.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public neurology source material; qualified clinician review pending.');
