INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-REN-ACUTEKIDNEYINJURY', 'Acute kidney injury', 'Acute kidney injury is a renal or genitourinary entity in which a rapid fall in filtration or urine output results from prerenal, intrinsic, or obstructive physiology.', 'Renal and Genitourinary', '1', 'Acute, subacute, or chronic according to the defining renal physiology and onset pattern.', 'Emergent when filtration failure, arrhythmia risk, sepsis, obstruction, or neurologic symptoms are present.', 'Volume loss, shock, nephrotoxins, pigment, obstruction, and cardiorenal or hepatorenal states are key contexts.', 'Volume loss, shock, nephrotoxins, pigment, obstruction, and cardiorenal or hepatorenal states are key contexts.', 'A rapid fall in filtration or urine output results from prerenal, intrinsic, or obstructive physiology.', 'Volume status, urine output, urinalysis, sediment, electrolyte pattern, and focal urinary symptoms identify the clinical syndrome.', 'Interpret creatinine trend, urine microscopy, volume status, medications, and systemic context together rather than relying on one index.', 'A single creatinine, fractional-excretion index, dipstick result, or image does not replace timing, volume assessment, medications, and urine sediment.', 'Anuria, dangerous potassium or acid-base disturbance, pulmonary edema, sepsis, infected obstruction, severe hypertension, or uremic complication requires immediate escalation.', 'Use serial renal and urine monitoring, mechanism-specific treatment, and nephrology or urology consultation when high-risk physiology is present.', 'Outcome depends on mechanism reversal, residual renal function, cardiovascular risk, complications, and timely specialty care.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public renal guidance; qualified clinician review pending.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-REN-PYELONEPHRITIS', 'Pyelonephritis', 'Pyelonephritis is a renal or genitourinary entity in which urinary infection ranges from bladder-limited symptoms to upper-tract or obstructed infection.', 'Renal and Genitourinary', '1', 'Acute, subacute, or chronic according to the defining renal physiology and onset pattern.', 'Emergent when filtration failure, arrhythmia risk, sepsis, obstruction, or neurologic symptoms are present.', 'Catheters, obstruction, pregnancy, reflux, diabetes, and immunocompromise modify risk.', 'Catheters, obstruction, pregnancy, reflux, diabetes, and immunocompromise modify risk.', 'Urinary infection ranges from bladder-limited symptoms to upper-tract or obstructed infection.', 'Volume status, urine output, urinalysis, sediment, electrolyte pattern, and focal urinary symptoms identify the clinical syndrome.', 'Interpret creatinine trend, urine microscopy, volume status, medications, and systemic context together rather than relying on one index.', 'A single creatinine, fractional-excretion index, dipstick result, or image does not replace timing, volume assessment, medications, and urine sediment.', 'Anuria, dangerous potassium or acid-base disturbance, pulmonary edema, sepsis, infected obstruction, severe hypertension, or uremic complication requires immediate escalation.', 'Use serial renal and urine monitoring, mechanism-specific treatment, and nephrology or urology consultation when high-risk physiology is present.', 'Outcome depends on mechanism reversal, residual renal function, cardiovascular risk, complications, and timely specialty care.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public renal guidance; qualified clinician review pending.');
INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-REN-RENALCOLIC', 'Renal colic', 'Renal colic is a renal or genitourinary entity in which urinary crystals or calculi obstruct or irritate the collecting system.', 'Renal and Genitourinary', '2', 'Acute, subacute, or chronic according to the defining renal physiology and onset pattern.', 'Emergent when filtration failure, arrhythmia risk, sepsis, obstruction, or neurologic symptoms are present.', 'Low urine volume, pH, diet, infection, medications, and inherited disease determine stone risk.', 'Low urine volume, pH, diet, infection, medications, and inherited disease determine stone risk.', 'Urinary crystals or calculi obstruct or irritate the collecting system.', 'Volume status, urine output, urinalysis, sediment, electrolyte pattern, and focal urinary symptoms identify the clinical syndrome.', 'Interpret creatinine trend, urine microscopy, volume status, medications, and systemic context together rather than relying on one index.', 'A single creatinine, fractional-excretion index, dipstick result, or image does not replace timing, volume assessment, medications, and urine sediment.', 'Anuria, dangerous potassium or acid-base disturbance, pulmonary edema, sepsis, infected obstruction, severe hypertension, or uremic complication requires immediate escalation.', 'Use serial renal and urine monitoring, mechanism-specific treatment, and nephrology or urology consultation when high-risk physiology is present.', 'Outcome depends on mechanism reversal, residual renal function, cardiovascular risk, complications, and timely specialty care.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public renal guidance; qualified clinician review pending.');
