INSERT INTO diseases (disease_id, canonical_name, concise_definition, organ_system_primary, board_exam_priority, time_course, severity_or_acuity, epidemiology_summary, risk_factors_summary, pathophysiology_summary, classic_presentation_summary, key_distinguishing_features, common_board_traps, emergency_red_flags, disposition_summary, prognosis_summary, last_reviewed_date, replacement_disease_id, source_review_status, medical_review_status, deprecated, notes) VALUES ('DIS-REN-CHRONICKIDNEYDISEASE', 'Chronic kidney disease', 'Chronic kidney disease is a renal or genitourinary entity in which persistent kidney damage or reduced filtration increases metabolic, cardiovascular, hematologic, and medication-toxicity risk.', 'Renal and Genitourinary', '2', 'Acute, subacute, or chronic according to the defining renal physiology and onset pattern.', 'Emergent when filtration failure, arrhythmia risk, sepsis, obstruction, or neurologic symptoms are present.', 'Diabetes, hypertension, inherited disease, glomerular disease, reflux, and nephrotoxins are common causes.', 'Diabetes, hypertension, inherited disease, glomerular disease, reflux, and nephrotoxins are common causes.', 'Persistent kidney damage or reduced filtration increases metabolic, cardiovascular, hematologic, and medication-toxicity risk.', 'Volume status, urine output, urinalysis, sediment, electrolyte pattern, and focal urinary symptoms identify the clinical syndrome.', 'Interpret creatinine trend, urine microscopy, volume status, medications, and systemic context together rather than relying on one index.', 'A single creatinine, fractional-excretion index, dipstick result, or image does not replace timing, volume assessment, medications, and urine sediment.', 'Anuria, dangerous potassium or acid-base disturbance, pulmonary edema, sepsis, infected obstruction, severe hypertension, or uremic complication requires immediate escalation.', 'Use serial renal and urine monitoring, mechanism-specific treatment, and nephrology or urology consultation when high-risk physiology is present.', 'Outcome depends on mechanism reversal, residual renal function, cardiovascular risk, complications, and timely specialty care.', '', '', 'source_checked', 'needs_medical_review', 'false', 'Original educational summary linked to authoritative public renal guidance; qualified clinician review pending.');
